CREATE TABLE hoj_a(k int, k2 text, v int);
CREATE TABLE hoj_b(k int, k2 text, w int);
CREATE TABLE hoj_e(k int, w int);
INSERT INTO hoj_a VALUES (1, 'x', 10), (1, 'x', 11), (2, 'y', 20), (3, 'z', 30), (NULL, 'n', 40), (5, NULL, 50);
INSERT INTO hoj_b VALUES (1, 'x', 100), (1, 'x', 101), (2, 'q', 200), (4, 'z', 400), (NULL, 'n', 500), (5, NULL, 600);
SELECT a.k, a.v, b.k, b.w FROM hoj_a a RIGHT JOIN hoj_b b ON a.k = b.k ORDER BY b.w, a.v;
SELECT a.k, a.v, b.k, b.w FROM hoj_a a FULL JOIN hoj_b b ON a.k = b.k ORDER BY a.v NULLS FIRST, b.w NULLS FIRST;
SELECT a.v, b.w FROM hoj_a a LEFT JOIN hoj_b b ON a.k = b.k ORDER BY a.v, b.w;
SELECT a.v, b.w FROM hoj_a a RIGHT JOIN hoj_b b ON a.k = b.k AND a.v + 90 < b.w ORDER BY b.w, a.v;
SELECT a.v, b.w FROM hoj_a a FULL JOIN hoj_b b ON a.k = b.k AND a.v + 90 < b.w ORDER BY a.v NULLS FIRST, b.w NULLS FIRST;
SELECT a.v, b.w FROM hoj_a a FULL JOIN hoj_b b ON a.k = b.k AND a.k2 = b.k2 ORDER BY a.v NULLS FIRST, b.w NULLS FIRST;
SELECT a.v, b.w FROM hoj_a a RIGHT JOIN hoj_b b ON a.k = b.k AND a.k2 = b.k2 ORDER BY b.w, a.v;
SELECT * FROM hoj_a a FULL JOIN hoj_b b USING (k) ORDER BY k NULLS FIRST, v NULLS FIRST, w NULLS FIRST;
SELECT k, k2, v, w FROM hoj_a NATURAL FULL JOIN hoj_b ORDER BY k NULLS FIRST, k2 NULLS FIRST, v NULLS FIRST, w NULLS FIRST;
SELECT * FROM hoj_a a RIGHT JOIN hoj_b b USING (k, k2) ORDER BY w, v;
SELECT a.v, b.w FROM hoj_a a FULL JOIN hoj_b b ON a.k = b.k WHERE b.w IS NULL OR b.w > 150 ORDER BY a.v NULLS FIRST, b.w NULLS FIRST;
SELECT a.v, b.w FROM hoj_a a RIGHT JOIN hoj_b b ON a.k = b.k WHERE a.v IS NULL ORDER BY b.w;
SELECT a.v, b.w FROM hoj_a a FULL JOIN hoj_b b ON a.k = b.k WHERE coalesce(a.v, 0) < 25 ORDER BY a.v NULLS FIRST, b.w NULLS FIRST;
SELECT a.v, e.w FROM hoj_a a FULL JOIN hoj_e e ON a.k = e.k ORDER BY a.v;
SELECT a.v, e.w FROM hoj_e e FULL JOIN hoj_a a ON a.k = e.k ORDER BY a.v;
SELECT a.v, e.w FROM hoj_a a RIGHT JOIN hoj_e e ON a.k = e.k ORDER BY a.v;
SELECT a.v, e.w FROM hoj_e e RIGHT JOIN hoj_a a ON a.k = e.k ORDER BY a.v;
SELECT count(*), count(a.v), count(b.w) FROM hoj_a a FULL JOIN hoj_b b ON a.k = b.k;
SELECT a.v, b.w FROM hoj_a a FULL JOIN hoj_b b ON a.k = b.k AND a.v > 15 ORDER BY a.v NULLS FIRST, b.w NULLS FIRST;
SELECT a.v, b.w FROM hoj_a a FULL JOIN hoj_b b ON a.k = b.k AND b.w < 150 ORDER BY a.v NULLS FIRST, b.w NULLS FIRST;
SELECT a.v, b.w FROM hoj_a a FULL JOIN hoj_b b ON a.k = b.k AND a.v / (b.w - 101) > 0 ORDER BY 1, 2;
SELECT a.v, b.w FROM hoj_a a FULL JOIN hoj_b b ON a.k = b.k AND a.v < b.w OR a.v = 50 ORDER BY 1, 2;
SELECT a.v, b.w FROM (SELECT * FROM hoj_a) a FULL JOIN (VALUES (1, 7), (NULL, 8), (9, 9)) b(k, w) ON a.k = b.k ORDER BY a.v NULLS FIRST, b.w;
DROP TABLE hoj_a, hoj_b, hoj_e;
